using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.DTOs;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Operations.SupplierReceipts;public class CreateModel(ApplicationDbContext db,ITransactionService transactions,IPermissionService permissions):PageModel
{[BindProperty]public SupplierReceiptForm Item{get;set;}=new();public SelectList Suppliers{get;private set;}=null!;public SelectList Materials{get;private set;}=null!;public async Task<IActionResult> OnGetAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.SupplierReceipts,PermissionAction.Add))return Forbid();await Load();return Page();}public async Task<IActionResult> OnPostAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.SupplierReceipts,PermissionAction.Add))return Forbid();if(ModelState.IsValid)try{await transactions.CreateSupplierReceiptAsync(new(Item.SupplierId,Item.MaterialId,Item.Date,Item.PolicyNumber,Item.Quantity,Item.UnitPrice,Item.TaxPercent,Item.Details));TempData["Message"]="تم تسجيل استلام البضاعة";return RedirectToPage("Index");}catch(InvalidOperationException e){ModelState.AddModelError(string.Empty,e.Message);}await Load();return Page();}private async Task Load(){Suppliers=new(await db.Suppliers.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name");Materials=new(await db.Materials.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name");}}
